# =============================================================================
# tests/district_claims.R — numbers the district prose states, with the query
# that checks each. Sourced by tests/verify_claims.R, which supplies `ATT` (the
# per-student attendance CTEs) and `OCT1` (the October 1 enrollment filter).
# Each entry: tab, claim, query (scalar, or a result whose ROW COUNT is the
# claim), stated value. Add a row whenever district prose quotes a figure.
# =============================================================================
COH_BASE <- "WITH cohort AS (SELECT student_id FROM students WHERE entered_9th_year = YR), last_spell AS (SELECT e.student_id, e.school_year, e.end_status, ROW_NUMBER() OVER (PARTITION BY e.student_id ORDER BY e.start_date DESC, e.enrollment_id DESC) AS rn FROM enrollments e JOIN cohort c ON c.student_id = e.student_id WHERE e.service_type = 'P' AND e.school_year <= LAST), outcome AS (SELECT l.student_id, l.end_status, CASE WHEN l.end_status = 'GRAD' THEN 'G' WHEN sc.documented_transfer = 1 THEN 'T' ELSE 'N' END AS o FROM last_spell l LEFT JOIN status_codes sc ON sc.code = l.end_status AND sc.code_type = 'end' WHERE l.rn = 1) "
COH25 <- sub("LAST", "2025", sub("YR", "2022", COH_BASE))
COH24 <- sub("LAST", "2024", sub("YR", "2021", COH_BASE))
