  c("dis", "one expulsion",                         "SELECT COUNT(*) FROM resolutions r JOIN incidents i USING (incident_id) WHERE r.resolution_code = 'EXP' AND i.incident_date BETWEEN '2024-07-01' AND '2025-06-30'", 1),
  c("dis", "129 students removed",                  "SELECT COUNT(DISTINCT r.student_id) FROM resolutions r JOIN incidents i USING (incident_id) WHERE r.resolution_code IN ('OSS', 'EXP') AND i.incident_date BETWEEN '2024-07-01' AND '2025-06-30'", 129),
  c("dis", "1,434 served in 2024-25",               "SELECT COUNT(DISTINCT student_id) FROM enrollments WHERE school_year = 2025 AND service_type = 'P'", 1434),
