  c("dis", "481 days removed",                      "SELECT SUM(days_removed) FROM resolutions r JOIN incidents i USING (incident_id) WHERE r.resolution_code IN ('OSS', 'EXP') AND i.incident_date BETWEEN '2024-07-01' AND '2025-06-30'", 481),
  c("dis", "119 American Indian (Minnesota) on Oct 1", paste("SELECT SUM(race_american_indian) FROM students WHERE student_id IN (SELECT student_id FROM enrollments WHERE", OCT1, ")"), 119),
