  c("dis", "Black students 10.6% suspended",        "SELECT ROUND(100.0 * SUM(x.student_id IS NOT NULL) / COUNT(*), 1) FROM (SELECT DISTINCT student_id FROM enrollments WHERE school_year = 2025 AND service_type = 'P') v JOIN students s USING (student_id) LEFT JOIN (SELECT DISTINCT r.student_id FROM resolutions r JOIN incidents i USING (incident_id) WHERE i.incident_date BETWEEN '2024-07-01' AND '2025-06-30' AND r.resolution_code IN ('OSS', 'EXP')) x USING (student_id) WHERE s.hispanic_latino = 0 AND s.race_black = 1 AND s.race_american_indian + s.race_asian + s.race_pacific_islander + s.race_white = 0", 10.6),
  c("dis", "white students 6.8% suspended",         "SELECT ROUND(100.0 * SUM(x.student_id IS NOT NULL) / COUNT(*), 1) FROM (SELECT DISTINCT student_id FROM enrollments WHERE school_year = 2025 AND service_type = 'P') v JOIN students s USING (student_id) LEFT JOIN (SELECT DISTINCT r.student_id FROM resolutions r JOIN incidents i USING (incident_id) WHERE i.incident_date BETWEEN '2024-07-01' AND '2025-06-30' AND r.resolution_code IN ('OSS', 'EXP')) x USING (student_id) WHERE s.hispanic_latino = 0 AND s.race_white = 1 AND s.race_american_indian + s.race_asian + s.race_pacific_islander + s.race_black = 0", 6.8),
  c("dis", "three Pacific Islander students, none suspended", "SELECT COUNT(*) FROM (SELECT DISTINCT student_id FROM enrollments WHERE school_year = 2025 AND service_type = 'P') v JOIN students s USING (student_id) WHERE s.hispanic_latino = 0 AND s.race_pacific_islander = 1 AND s.race_american_indian + s.race_asian + s.race_black + s.race_white = 0", 3),
